const { useState } = React;

function App() {
  const [form, setForm] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phone: "",
    country: "",
    password: "",
    gender: "",
  });

  const [errors, setErrors] = useState({});

  function handleChange(e) {
    const { name, value } = e.target;
    setForm((f) => ({ ...f, [name]: value }));
    setErrors((errs) => ({ ...errs, [name]: "" }));
  }

  function validate() {
    const newErrors = {};
    if (!form.firstName.trim()) newErrors.firstName = "First name is required.";
    if (!form.lastName.trim()) newErrors.lastName = "Last name is required.";
    if (!form.email.trim()) newErrors.email = "Email is required.";
    if (!form.phone.trim()) newErrors.phone = "Phone is required.";
    if (!form.country.trim()) newErrors.country = "Country is required.";
    if (!form.password.trim()) newErrors.password = "Password is required.";
    if (!form.gender.trim()) newErrors.gender = "Gender is required.";
    return newErrors;
  }

  function handleSubmit(e) {
    e.preventDefault();
    const validationErrors = validate();
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
    } else {
      alert("Account created successfully!");
      // Reset form
      setForm({
        firstName: "",
        lastName: "",
        email: "",
        phone: "",
        country: "",
        password: "",
        gender: "",
      });
      setErrors({});
    }
  }

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen,
            Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
          background: #f9f7f1;
          display: flex;
          justify-content: center;
          align-items: center;
          height: 100vh;
        }
        .card {
          background: white;
          padding: 24px 32px;
          border-radius: 8px;
          box-shadow: 0 4px 12px rgb(0 0 0 / 0.1);
          width: 360px;
        }
        h2 {
          margin-top: 0;
          margin-bottom: 24px;
          font-weight: 600;
          border-bottom: 2px solid #333;
          padding-bottom: 4px;
          font-size: 1.5rem;
        }
        form {
          display: flex;
          flex-direction: column;
          gap: 16px;
        }
        .row {
          display: flex;
          gap: 12px;
        }
        .row > * {
          flex: 1;
        }
        label {
          display: flex;
          flex-direction: column;
          font-size: 0.9rem;
          color: #333;
        }
        input[type="text"],
        input[type="email"],
        input[type="tel"],
        input[type="password"],
        select {
          margin-top: 6px;
          padding: 8px 10px;
          font-size: 1rem;
          border: 1.5px solid #ccc;
          border-radius: 6px;
          transition: border-color 0.2s ease;
        }
        input[type="text"]:focus,
        input[type="email"]:focus,
        input[type="tel"]:focus,
        input[type="password"]:focus,
        select:focus {
          outline: none;
          border-color: #007bff;
        }
        .error {
          color: #d93025;
          font-size: 0.8rem;
          margin-top: 4px;
        }
        .phone-country-row {
          display: flex;
          gap: 12px;
        }
        .phone-country-row > * {
          flex: 1;
        }
        .gender-group {
          display: flex;
          gap: 24px;
          align-items: center;
          margin-top: 4px;
        }
        .gender-label {
          display: flex;
          align-items: center;
          gap: 6px;
          font-size: 0.95rem;
          cursor: pointer;
          user-select: none;
        }
        button {
          margin-top: 12px;
          padding: 10px 16px;
          font-size: 1rem;
          font-weight: 600;
          background-color: #007bff;
          color: white;
          border: none;
          border-radius: 8px;
          cursor: pointer;
          transition: background-color 0.2s ease;
        }
        button:hover {
          background-color: #0056b3;
        }
      `}</style>
      <main>
        <section className="card" aria-label="Sign up form">
          <h2>Sign up</h2>
          <form onSubmit={handleSubmit} noValidate>
            <div className="row">
              <label htmlFor="firstName">
                First name
                <input
                  type="text"
                  id="firstName"
                  name="firstName"
                  value={form.firstName}
                  onChange={handleChange}
                  aria-describedby={errors.firstName ? "firstName-error" : undefined}
                  aria-invalid={errors.firstName ? "true" : "false"}
                />
                {errors.firstName && (
                  <span className="error" role="alert" id="firstName-error">
                    {errors.firstName}
                  </span>
                )}
              </label>
              <label htmlFor="lastName">
                Last name
                <input
                  type="text"
                  id="lastName"
                  name="lastName"
                  value={form.lastName}
                  onChange={handleChange}
                  aria-describedby={errors.lastName ? "lastName-error" : undefined}
                  aria-invalid={errors.lastName ? "true" : "false"}
                />
                {errors.lastName && (
                  <span className="error" role="alert" id="lastName-error">
                    {errors.lastName}
                  </span>
                )}
              </label>
            </div>

            <label htmlFor="email">
              Email
              <input
                type="email"
                id="email"
                name="email"
                value={form.email}
                onChange={handleChange}
                aria-describedby={errors.email ? "email-error" : undefined}
                aria-invalid={errors.email ? "true" : "false"}
              />
              {errors.email && (
                <span className="error" role="alert" id="email-error">
                  {errors.email}
                </span>
              )}
            </label>

            <div className="phone-country-row">
              <label htmlFor="phone">
                Phone
                <input
                  type="tel"
                  id="phone"
                  name="phone"
                  value={form.phone}
                  onChange={handleChange}
                  aria-describedby={errors.phone ? "phone-error" : undefined}
                  aria-invalid={errors.phone ? "true" : "false"}
                />
                {errors.phone && (
                  <span className="error" role="alert" id="phone-error">
                    {errors.phone}
                  </span>
                )}
              </label>

              <label htmlFor="country">
                Country
                <select
                  id="country"
                  name="country"
                  value={form.country}
                  onChange={handleChange}
                  aria-describedby={errors.country ? "country-error" : undefined}
                  aria-invalid={errors.country ? "true" : "false"}
                >
                  <option value="">Select country</option>
                  <option value="India">India</option>
                  <option value="USA">USA</option>
                  <option value="UK">UK</option>
                </select>
                {errors.country && (
                  <span className="error" role="alert" id="country-error">
                    {errors.country}
                  </span>
                )}
              </label>
            </div>

            <label htmlFor="password">
              Password
              <input
                type="password"
                id="password"
                name="password"
                value={form.password}
                onChange={handleChange}
                aria-describedby={errors.password ? "password-error" : undefined}
                aria-invalid={errors.password ? "true" : "false"}
              />
              {errors.password && (
                <span className="error" role="alert" id="password-error">
                  {errors.password}
                </span>
              )}
            </label>

            <fieldset style={{ border: "none", padding: 0, margin: 0 }}>
              <legend style={{ fontWeight: "600", marginBottom: "8px" }}>Gender</legend>
              <div className="gender-group">
                <label className="gender-label" htmlFor="male">
                  <input
                    type="radio"
                    id="male"
                    name="gender"
                    value="Male"
                    checked={form.gender === "Male"}
                    onChange={handleChange}
                    aria-describedby={errors.gender ? "gender-error" : undefined}
                    aria-invalid={errors.gender ? "true" : "false"}
                  />
                  Male
                </label>

                <label className="gender-label" htmlFor="female">
                  <input
                    type="radio"
                    id="female"
                    name="gender"
                    value="Female"
                    checked={form.gender === "Female"}
                    onChange={handleChange}
                    aria-describedby={errors.gender ? "gender-error" : undefined}
                    aria-invalid={errors.gender ? "true" : "false"}
                  />
                  Female
                </label>

                <label className="gender-label" htmlFor="other">
                  <input
                    type="radio"
                    id="other"
                    name="gender"
                    value="Other"
                    checked={form.gender === "Other"}
                    onChange={handleChange}
                    aria-describedby={errors.gender ? "gender-error" : undefined}
                    aria-invalid={errors.gender ? "true" : "false"}
                  />
                  Other
                </label>
              </div>
              {errors.gender && (
                <span className="error" role="alert" id="gender-error">
                  {errors.gender}
                </span>
              )}
            </fieldset>

            <button type="submit">Create account</button>
          </form>
        </section>
      </main>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

